import { NavGraph } from '../../src/shared/types';
import { validateNavGraphPayload } from '../domain/navGraphSchema';

// oxc workaround: export type declarations removed to avoid TypeScript export type parsing failure
// Types are used at compile time only (stripped by TypeScript); runtime value is undefined
export const MapApiErrorReason = undefined as unknown as MapApiErrorReason;

export interface MapApiError {
  endpoint: string;
  status: number | null;
  reason: MapApiErrorReason;
  attempt: number;
  message: string;
  details?: string[];
}

// oxc workaround: MapApiResult must be exported as both type and runtime value
export type MapApiResult<T> = {
  ok: true;
  endpoint: string;
  status: number;
  attempt: number;
  data: T;
} | {
  ok: false;
  error: MapApiError;
};
export const MapApiResult = undefined as unknown as MapApiResult<unknown>;

export interface MapImageContract {
  endpoint: string;
  contentType: string;
  cacheControl: string | null;
}

export interface FloorPlanTarget {
  buildingId: number;
  floorNumber: number;
}

export interface MapApiRetryPolicy {
  maxAttempts: number;
  baseDelayMs: number;
  timeoutMs: number;
}

export const Fetcher = undefined as unknown as Fetcher;

export interface MapApiClientConfig {
  baseUrl: string;
  fetchImpl?: Fetcher;
  retryPolicy?: Partial<MapApiRetryPolicy>;
  sleep?: (ms: number) => Promise<void>;
}

export interface MapApiRequestOptions {
  signal?: AbortSignal;
  maxAttempts?: number;
  timeoutMs?: number;
}

interface AttemptSignal {
  signal: AbortSignal;
  cleanup: () => void;
  didTimeout: () => boolean;
}

interface HttpSuccess {
  ok: true;
  endpoint: string;
  attempt: number;
  response: Response;
}

interface HttpFailure {
  ok: false;
  error: MapApiError;
}

type HttpMapResult = HttpSuccess | HttpFailure;
type HttpImageResult = HttpSuccess | HttpFailure;

export const MapGraphResult = undefined as unknown as MapGraphResult;
export const FloorPlanImageResult = undefined as unknown as FloorPlanImageResult;

const DEFAULT_RETRY_POLICY: MapApiRetryPolicy = {
  maxAttempts: 3,
  baseDelayMs: 200,
  timeoutMs: 2_000,
};

function withHardTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout>;
  return Promise.race([
    promise,
    new Promise<never>((_, reject) => {
      timeoutHandle = setTimeout(() => {
        reject(new Error('timeout'));
      }, timeoutMs);
    }),
  ]).finally(() => {
    clearTimeout(timeoutHandle!);
  });
}

function normalizeBaseUrl(baseUrl: string): string {
  const parsed = new URL(baseUrl);
  parsed.hash = '';
  parsed.search = '';
  return parsed.toString().replace(/\/$/, '');
}

function resolveEndpoint(baseUrl: string, pathname: string): string {
  return new URL(pathname, `${baseUrl}/`).toString();
}

function createApiError(
  endpoint: string,
  attempt: number,
  reason: MapApiErrorReason,
  message: string,
  status: number | null = null,
  details?: string[],
): MapApiError {
  return {
    endpoint,
    status,
    reason,
    attempt,
    message,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function isRetryableHttpStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

function isAbortError(error: unknown): boolean {
  // DOMException is not available in React Native Hermes
  if (typeof DOMException !== 'undefined' && error instanceof DOMException) {
    return error.name === 'AbortError';
  }
  return error instanceof Error && error.name === 'AbortError';
}

/** React Native-safe abort error (no DOMException in Hermes) */
function makeAbortError(): Error {
  const err = new Error('Aborted');
  err.name = 'AbortError';
  return err;
}

function createAttemptSignal(externalSignal: AbortSignal | undefined, timeoutMs: number) {
  const controller = new AbortController();
  let timeoutTriggered = false;

  const onExternalAbort = () => {
    controller.abort(externalSignal?.reason);
  };

  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort(externalSignal.reason);
    } else {
      externalSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
  }

  const timeoutHandle = setTimeout(() => {
    timeoutTriggered = true;
    controller.abort(new Error('timeout'));
  }, timeoutMs);

  const cleanup = () => {
    clearTimeout(timeoutHandle);
    if (externalSignal && !externalSignal.aborted) {
      externalSignal.removeEventListener('abort', onExternalAbort);
    }
  };

  return {
    signal: controller.signal,
    cleanup,
    didTimeout: () => timeoutTriggered,
  };
}

function createSleepWithSignal(
  sleepImpl: (ms: number) => Promise<void>,
  signal: AbortSignal | undefined,
) {
  return async (ms: number) => {
    if (ms <= 0) {
      return;
    }

    if (!signal) {
      await sleepImpl(ms);
      return;
    }

    if (signal.aborted) {
      throw makeAbortError();
    }

    await new Promise<void>((resolve, reject) => {
      const timeoutHandle = setTimeout(() => {
        signal.removeEventListener('abort', onAbort);
        resolve();
      }, ms);

      const onAbort = () => {
        clearTimeout(timeoutHandle);
        reject(makeAbortError());
      };

      signal.addEventListener('abort', onAbort, { once: true });
    });
  };
}

export interface MapApiClient {
  fetchMapGraph(options?: MapApiRequestOptions): Promise<MapGraphResult>;
  fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<FloorPlanImageResult>;
  fetchCampusImageContract(options?: MapApiRequestOptions): Promise<FloorPlanImageResult>;
  resolveMapUrl(): string;
  resolveFloorPlanImageUrl(target: FloorPlanTarget): string;
  resolveCampusImageUrl(): string;
}

export function createMapApiClient(config: MapApiClientConfig): MapApiClient {
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const fetchImpl: Fetcher =
    config.fetchImpl ?? ((input, init) => fetch(input, init));
  const retryPolicy: MapApiRetryPolicy = {
    ...DEFAULT_RETRY_POLICY,
    ...config.retryPolicy,
  };
  const sleepImpl = config.sleep ?? ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)));

  async function executeGet(
    endpoint: string,
    options: MapApiRequestOptions | undefined,
  ): Promise<HttpMapResult> {
    const maxAttempts = options?.maxAttempts ?? retryPolicy.maxAttempts;
    const timeoutMs = options?.timeoutMs ?? retryPolicy.timeoutMs;
    const sleepWithSignal = createSleepWithSignal(sleepImpl, options?.signal);

    let lastError: MapApiError | null = null;

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      try {
        const response = await withHardTimeout(
          fetchImpl(endpoint, { method: 'GET' }),
          timeoutMs,
        );

        if (!response.ok) {
          const error = createApiError(
            endpoint,
            attempt,
            'http-error',
            `Request failed with HTTP ${response.status}.`,
            response.status,
          );

          if (attempt < maxAttempts && isRetryableHttpStatus(response.status)) {
            lastError = error;
            const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
            try {
              await sleepWithSignal(delay);
            } catch {
              break;
            }
            continue;
          }

          return { ok: false, error };
        }

        return {
          ok: true,
          endpoint,
          attempt,
          response,
        };
      } catch (error) {
        const isTimeout = error instanceof Error && error.message === 'timeout';
        const reason: MapApiErrorReason = isTimeout
          ? 'timeout'
          : (options?.signal?.aborted || isAbortError(error))
            ? 'aborted'
            : 'network-error';

        const apiError = createApiError(
          endpoint,
          attempt,
          reason,
          reason === 'timeout'
            ? `Request timed out after ${timeoutMs}ms.`
            : reason === 'aborted'
              ? 'Request was aborted.'
              : error instanceof Error
                ? error.message
                : 'Network request failed.',
        );

        const shouldRetry = reason !== 'aborted' && attempt < maxAttempts;
        if (shouldRetry) {
          lastError = apiError;
          const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
          try {
            await sleepWithSignal(delay);
          } catch {
            break;
          }
          continue;
        }

        return { ok: false, error: apiError };
      }
    }

    return {
      ok: false,
      error:
        lastError ??
        createApiError(endpoint, maxAttempts, 'network-error', 'Request failed after retries.'),
    };
  }

  async function fetchMapGraph(options?: MapApiRequestOptions): Promise<MapGraphResult> {
    const endpoint = resolveMapEndpoint(baseUrl);
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    let payload: unknown;

    try {
      payload = await responseResult.response.json();
    } catch (error) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'invalid-json',
          error instanceof Error ? error.message : 'Response body is not valid JSON.',
          responseResult.response.status,
        ),
      };
    }

    const validated = validateNavGraphPayload(payload);
    if (!validated.ok) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'contract-validation-error',
          validated.error.message,
          responseResult.response.status,
          validated.error.issues,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: validated.data,
    };
  }

  async function fetchImageContract(
    endpoint: string,
    options?: MapApiRequestOptions,
  ): Promise<FloorPlanImageResult> {
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    const contentType = responseResult.response.headers.get('content-type');
    if (!contentType || !contentType.toLowerCase().startsWith('image/')) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'unexpected-content-type',
          `Expected image content-type but received "${contentType ?? 'missing'}".`,
          responseResult.response.status,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: {
        endpoint,
        contentType,
        cacheControl: responseResult.response.headers.get('cache-control'),
      },
    };
  }

  function resolveMapUrl(): string {
    return resolveMapEndpoint(baseUrl);
  }

  function resolveFloorPlanImageUrl(target: FloorPlanTarget): string {
    return resolveFloorPlanImageEndpoint(baseUrl, target);
  }

  function resolveCampusImageUrl(): string {
    return resolveCampusImageEndpoint(baseUrl);
  }

  async function fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<FloorPlanImageResult> {
    return fetchImageContract(resolveFloorPlanImageUrl(target), options);
  }

  async function fetchCampusImageContract(options?: MapApiRequestOptions): Promise<FloorPlanImageResult> {
    return fetchImageContract(resolveCampusImageUrl(), options);
  }

  return {
    fetchMapGraph,
    fetchFloorPlanImageContract,
    fetchCampusImageContract,
    resolveMapUrl,
    resolveFloorPlanImageUrl,
    resolveCampusImageUrl,
  };
}

export function resolveMapEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/map');
}

export function resolveFloorPlanImageEndpoint(baseUrl: string, target: FloorPlanTarget): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  const buildingId = Number(target.buildingId);
  const floorNumber = Number(target.floorNumber);
  return resolveEndpoint(normalizedBaseUrl, `/api/floor-plan/${buildingId}/${floorNumber}`);
}

export function resolveCampusImageEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/campus/image');
}

import { NavGraph } from '../../src/shared/types';
import { describe, expect, it, vi } from 'vitest';
import {
  type Fetcher,
  createMapApiClient,
  resolveCampusImageEndpoint,
  resolveFloorPlanImageEndpoint,
  resolveMapEndpoint,
} from './mapApiClient';

function createGraphFixture(): NavGraph {
  return {
    buildings: [
      {
        id: 1,
        name: 'Engineering',
        floors: [
          {
            id: 11,
            floorNumber: 1,
            imagePath: 'floor-plan-1-1.png',
            updatedAt: '2026-01-01T00:00:00.000Z',
            nodes: [
              {
                id: 'entrance-1',
                x: 0.1,
                y: 0.2,
                label: 'Main Entrance',
                type: 'entrance',
                searchable: true,
                floorId: 11,
              },
              {
                id: 'stairs-1',
                x: 0.3,
                y: 0.4,
                label: 'Stairs',
                type: 'stairs',
                searchable: false,
                floorId: 11,
                connectsToFloorAboveId: 12,
                connectsToNodeAboveId: 'stairs-2',
              },
            ],
            edges: [
              {
                id: 'edge-1',
                sourceId: 'entrance-1',
                targetId: 'stairs-1',
                standardWeight: 0.5,
                accessibleWeight: 10000000000,
                accessible: false,
                bidirectional: true,
              },
            ],
          },
        ],
      },
    ],
  };
}

describe('mapApiClient', () => {
  it('resolves endpoint URLs for map, floor image, and campus image', () => {
    expect(resolveMapEndpoint('https://campusnav.example.com/')).toBe('https://campusnav.example.com/api/map');
    expect(resolveFloorPlanImageEndpoint('https://campusnav.example.com', { buildingId: 4, floorNumber: 2 })).toBe(
      'https://campusnav.example.com/api/floor-plan/4/2',
    );
    expect(resolveCampusImageEndpoint('https://campusnav.example.com')).toBe(
      'https://campusnav.example.com/api/campus/image',
    );
  });

  it('fetches and validates map payload successfully', async () => {
    const payload = createGraphFixture();
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(
      new Response(JSON.stringify(payload), {
        status: 200,
        headers: {
          'content-type': 'application/json',
        },
      }),
    );

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 2, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(true);
    if (!result.ok) {
      throw new Error('Expected map request to succeed.');
    }

    expect(result.endpoint).toBe('https://campusnav.example.com/api/map');
    expect(result.status).toBe(200);
    expect(result.attempt).toBe(1);
    expect(result.data.buildings[0]?.floors[0]?.nodes[1]?.connectsToNodeAboveId).toBe('stairs-2');
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it('retries retryable HTTP failures and reports successful attempt count', async () => {
    const payload = createGraphFixture();
    const fetchImpl = vi
      .fn<Fetcher>()
      .mockResolvedValueOnce(new Response('service unavailable', { status: 500 }))
      .mockResolvedValueOnce(
        new Response(JSON.stringify(payload), {
          status: 200,
          headers: {
            'content-type': 'application/json',
          },
        }),
      );

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(true);
    if (!result.ok) {
      throw new Error('Expected map request to succeed after retry.');
    }

    expect(result.attempt).toBe(2);
    expect(fetchImpl).toHaveBeenCalledTimes(2);
  });

  it('returns structured endpoint/status/reason metadata for non-retryable HTTP errors', async () => {
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(new Response('missing', { status: 404 }));
    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected HTTP failure.');
    }

    expect(result.error.endpoint).toBe('https://campusnav.example.com/api/map');
    expect(result.error.status).toBe(404);
    expect(result.error.reason).toBe('http-error');
    expect(result.error.attempt).toBe(1);
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it('classifies timeout failures after bounded retries', async () => {
    const timeoutFetch = vi.fn<Fetcher>((_input, init) => {
      return new Promise<Response>((_, reject) => {
        init?.signal?.addEventListener(
          'abort',
          () => reject(new DOMException('Aborted', 'AbortError')),
          { once: true },
        );
      });
    });

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl: timeoutFetch,
      retryPolicy: { maxAttempts: 2, baseDelayMs: 0, timeoutMs: 5 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected timeout failure.');
    }

    expect(result.error.reason).toBe('timeout');
    expect(result.error.attempt).toBe(2);
    expect(result.error.status).toBeNull();
    expect(timeoutFetch).toHaveBeenCalledTimes(2);
  });

  it('classifies caller cancellation as aborted without extra retries', async () => {
    const abortingFetch = vi.fn<Fetcher>((_input, init) => {
      return new Promise<Response>((_, reject) => {
        const signal = init?.signal;

        if (signal?.aborted) {
          reject(new DOMException('Aborted', 'AbortError'));
          return;
        }

        signal?.addEventListener(
          'abort',
          () => reject(new DOMException('Aborted', 'AbortError')),
          { once: true },
        );
      });
    });

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl: abortingFetch,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0, timeoutMs: 50 },
    });

    const controller = new AbortController();
    controller.abort();

    const result = await client.fetchMapGraph({ signal: controller.signal });

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected aborted request result.');
    }

    expect(result.error.reason).toBe('aborted');
    expect(result.error.attempt).toBe(1);
    expect(abortingFetch).toHaveBeenCalledTimes(1);
  });

  it('returns invalid-json when response body cannot be parsed as JSON', async () => {
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(
      new Response('this is not json', {
        status: 200,
        headers: { 'content-type': 'application/json' },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected invalid JSON failure.');
    }

    expect(result.error.reason).toBe('invalid-json');
    expect(result.error.status).toBe(200);
    expect(result.error.endpoint).toContain('/api/map');
  });

  it('returns contract-validation-error with details for malformed map payloads', async () => {
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(
      new Response(JSON.stringify({ foo: 'bar' }), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected contract validation failure.');
    }

    expect(result.error.reason).toBe('contract-validation-error');
    expect(result.error.details?.[0]).toContain('buildings');
    expect(result.error.endpoint).toBe('https://campusnav.example.com/api/map');
  });

  it('returns unexpected-content-type for image contract endpoints with non-image responses', async () => {
    const fetchImpl = vi.fn<Fetcher>().mockResolvedValue(
      new Response('not image', {
        status: 200,
        headers: {
          'content-type': 'application/json',
        },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchCampusImageContract();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected image content-type failure.');
    }

    expect(result.error.reason).toBe('unexpected-content-type');
    expect(result.error.endpoint).toBe('https://campusnav.example.com/api/campus/image');
    expect(result.error.status).toBe(200);
  });
});

import { NavFloor } from '../../src/shared/types';
import { NormalizedNavGraph } from '../domain/navGraph';
import { normalizeNavGraph } from '../domain/navGraph';
import {
  type FloorPlanTarget,
  type MapApiClient,
  type MapApiErrorReason, MapApiResult, MapImageContract,
  createMapApiClient,
} from '../data/mapApiClient';
import { validateApiBaseUrl } from './appBootstrap';

export type MapBootstrapFetchPhase = 'map' | 'image';
export const MapBootstrapFetchPhase = undefined as unknown as MapBootstrapFetchPhase;

export type MapBootstrapErrorReason =
  | 'missing-api-base-url'
  | 'invalid-api-base-url'
  | MapApiErrorReason
  | 'normalization-failure'
  | 'empty-graph';
export const MapBootstrapErrorReason = undefined as unknown as MapBootstrapErrorReason;

export type MapBootstrapState =
  | {
      phase: 'idle';
      authRequired: false;
    }
  | {
      phase: 'loading';
      authRequired: false;
      attempt: number;
      startedAtMs: number;
      currentPhase: MapBootstrapFetchPhase;
      endpoint: string;
    }
  | {
      phase: 'ready';
      authRequired: false;
      attempt: number;
      apiBaseUrl: string;
      graph: NormalizedNavGraph;
      image: MapImageContract;
      imageTarget: FloorPlanTarget;
    }
  | {
      phase: 'error';
      authRequired: false;
      attempt: number;
      reason: MapBootstrapErrorReason;
      message: string;
      failedPhase: 'config' | MapBootstrapFetchPhase;
      endpoint: string | null;
      recoverable: boolean;
      details?: string[];
    };
export const MapBootstrapState = undefined as unknown as MapBootstrapState;

export interface MapBootstrapResult {
  state: MapBootstrapState;
  transitions: MapBootstrapState[];
}

export interface MapBootstrapOptions {
  env?: Record<string, string | undefined>;
  envUrl?: string;
  attempt?: number;
  now?: () => number;
  clientFactory?: (baseUrl: string) => MapApiClient;
}

const IDLE_STATE: MapBootstrapState = {
  phase: 'idle',
  authRequired: false,
};

export const IDLE_MAP_BOOTSTRAP_STATE = IDLE_STATE;

function loadingState(
  currentPhase: MapBootstrapFetchPhase,
  endpoint: string,
  attempt: number,
  now: () => number,
): MapBootstrapState {
  return {
    phase: 'loading',
    authRequired: false,
    attempt,
    startedAtMs: now(),
    currentPhase,
    endpoint,
  };
}

function toConfigError(reason: 'missing-api-base-url' | 'invalid-api-base-url', message: string, attempt: number): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason,
    message,
    failedPhase: 'config',
    endpoint: null,
    recoverable: false,
  };
}

function toMapApiError(
  failedPhase: MapBootstrapFetchPhase,
  attempt: number,
  result: Extract<MapApiResult<unknown>, { ok: false }>,
): MapBootstrapState {
  const isRecoverable = result.error.reason !== 'contract-validation-error';

  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: result.error.reason,
    message: result.error.message,
    failedPhase,
    endpoint: result.error.endpoint,
    recoverable: isRecoverable,
    ...(result.error.details ? { details: result.error.details } : {}),
  };
}

function toNormalizationError(
  attempt: number,
  endpoint: string,
  message: string,
  details?: string[],
): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: 'normalization-failure',
    message,
    failedPhase: 'map',
    endpoint,
    recoverable: false,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function toEmptyGraphError(attempt: number, endpoint: string): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: 'empty-graph',
    message: 'Map payload contained no floors to bootstrap.',
    failedPhase: 'map',
    endpoint,
    recoverable: false,
  };
}

function pickInitialFloor(graph: NormalizedNavGraph): FloorPlanTarget | null {
  for (const building of graph.graph.buildings) {
    const floor = pickFirstFloor(building.floors);
    if (!floor) {
      continue;
    }

    return {
      buildingId: building.id,
      floorNumber: floor.floorNumber,
    };
  }

  return null;
}

function pickFirstFloor(floors: NavFloor[]): NavFloor | null {
  if (floors.length === 0) {
    return null;
  }

  const sortedFloors = [...floors].sort((a, b) => a.floorNumber - b.floorNumber);
  return sortedFloors[0] ?? null;
}

export async function runMapBootstrap(options: MapBootstrapOptions = {}): Promise<MapBootstrapResult> {
  const attempt = Math.max(1, options.attempt ?? 1);
  const env = options.env ?? process.env;
  const now = options.now ?? Date.now;

  // Read env var directly in this scope where Metro has inlined it
  // options.envUrl takes precedence (passed from App.tsx where it was read correctly)
  const envUrl = options.envUrl ?? (typeof process !== 'undefined' ? process.env.EXPO_PUBLIC_API_BASE_URL : undefined);

  const apiBase = validateApiBaseUrl(
    envUrl && envUrl !== 'undefined'
      ? envUrl
      : 'http://10.0.2.2:8080',
  );
  if (!apiBase.ok) {
    const configError = toConfigError(apiBase.reason, apiBase.message, attempt);
    return {
      state: configError,
      transitions: [configError],
    };
  }

  const client = options.clientFactory
    ? options.clientFactory(apiBase.normalizedUrl)
    : createMapApiClient({ baseUrl: apiBase.normalizedUrl });

  const transitions: MapBootstrapState[] = [];

  const mapLoading = loadingState('map', client.resolveMapUrl(), attempt, now);
  transitions.push(mapLoading);

  const mapResult = await client.fetchMapGraph();
  if (!mapResult.ok) {
    const mapError = toMapApiError('map', attempt, mapResult);
    transitions.push(mapError);
    return {
      state: mapError,
      transitions,
    };
  }

  const normalized = normalizeNavGraph(mapResult.data);
  if (!normalized.ok) {
    const normalizationError = toNormalizationError(
      attempt,
      mapResult.endpoint,
      normalized.error.message,
      [normalized.error.code],
    );
    transitions.push(normalizationError);
    return {
      state: normalizationError,
      transitions,
    };
  }

  const imageTarget = pickInitialFloor(normalized.data);
  if (!imageTarget) {
    const emptyGraphError = toEmptyGraphError(attempt, mapResult.endpoint);
    transitions.push(emptyGraphError);
    return {
      state: emptyGraphError,
      transitions,
    };
  }

  const imageLoading = loadingState(
    'image',
    client.resolveFloorPlanImageUrl(imageTarget),
    attempt,
    now,
  );
  transitions.push(imageLoading);

  const imageResult = await client.fetchFloorPlanImageContract(imageTarget);

  let floorPlanImage: string | null = null;
  if (imageResult.ok) {
    floorPlanImage = imageResult.data ?? null;
  } else if (imageResult.error.reason === 'http-error' && imageResult.error.status === 404) {
    // Floor plan image not yet uploaded — skip gracefully, user sees empty floor plan
    console.warn('[mapBootstrap] Floor plan image not found, continuing without it');
  } else {
    const imageError = toMapApiError('image', attempt, imageResult);
    transitions.push(imageError);
    return {
      state: imageError,
      transitions,
    };
  }

  const readyState: MapBootstrapState = {
    phase: 'ready',
    authRequired: false,
    attempt,
    apiBaseUrl: apiBase.normalizedUrl,
    graph: normalized.data,
    image: floorPlanImage,
    imageTarget,
  };

  transitions.push(readyState);

  return {
    state: readyState,
    transitions,
  };
}

/**
 * DestinationPicker — building/floor/node accordion with fuzzy text search.
 * Pressing a node calls onNodeSelect. "Set Start" / "Set Destination" toggle
 * in header reflects the activeField from RouteSelection.
 */

import { useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

import { useLocationSearch } from '../../hooks/useLocationSearch';
import { NormalizedNavGraph } from '../../domain/navGraph';
import { NavNode } from '../../../src/shared/types';
import { RouteSelection } from '../../hooks/useRouteSelection';

const DEBOUNCE_MS = 300;

interface Props {
  graph: NormalizedNavGraph;
  selection: RouteSelection;
  onNodeSelect: (node: NavNode) => void;
}

const TYPE_BADGE: Record<string, string> = {
  room: '📍',
  entrance: '🚪',
  elevator: '🛗',
  restroom: '🚻',
  landmark: '⭐',
  stairs: '⬆️',
  ramp: '♿',
  junction: '⬡',
  hallway: '─',
};

const ACCESSIBLE_ICON = '♿';

export function DestinationPicker({ graph, selection, onNodeSelect }: Props) {
  const [query, setQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');

  // Debounce search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedQuery(query);
    }, DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  const { buildings, totalMatches } = useLocationSearch(graph, debouncedQuery);

  const activeLabel = selection.activeField === 'start' ? 'Set Start' : 'Set Destination';
  const otherLabel = selection.activeField === 'start' ? 'Set Destination' : 'Set Start';

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerLabel}>{activeLabel}</Text>
        <Text style={styles.resultCount}>
          {totalMatches} {totalMatches === 1 ? 'result' : 'results'}
        </Text>
      </View>

      {/* Search input */}
      <TextInput
        style={styles.searchInput}
        placeholder="Search location..."
        placeholderTextColor="#64748b"
        value={query}
        onChangeText={setQuery}
        autoCapitalize="none"
        autoCorrect={false}
      />

      {/* Active field indicator */}
      <View style={styles.fieldToggle}>
        <Text style={styles.fieldText}>Picking: </Text>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'start' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('start')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'start' && styles.fieldChipTextActive]}>
            Start {selection.start ? `(${selection.start.label})` : ''}
          </Text>
        </Pressable>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'destination' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('destination')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'destination' && styles.fieldChipTextActive]}>
            Dest {selection.destination ? `(${selection.destination.label})` : ''}
          </Text>
        </Pressable>
        {(selection.start || selection.destination) && (
          <Pressable style={styles.swapButton} onPress={selection.swap}>
            <Text style={styles.swapButtonText}>⇄ Swap</Text>
          </Pressable>
        )}
      </View>

      {/* Results */}
      <FlatList
        data={buildings}
        keyExtractor={item => String(item.buildingId)}
        style={styles.list}
        renderItem={({ item: building }) => (
          <BuildingAccordion
            building={building}
            onNodeSelect={onNodeSelect}
          />
        )}
        ListEmptyComponent={
          <Text style={styles.emptyText}>
            {debouncedQuery ? 'No locations match your search.' : 'No locations available.'}
          </Text>
        }
      />
    </View>
  );
}

/* ─── Sub-components ─── */

interface BuildingAccordionProps {
  building: import('../../hooks/useLocationSearch').SearchBuilding;
  onNodeSelect: (node: NavNode) => void;
}

function BuildingAccordion({ building, onNodeSelect }: BuildingAccordionProps) {
  const [expanded, setExpanded] = useState(false);

  return (
    <View style={styles.buildingSection}>
      <Pressable style={styles.buildingHeader} onPress={() => setExpanded(e => !e)}>
        <View style={styles.buildingInfo}>
          <Text style={styles.buildingName}>{building.buildingName}</Text>
          <Text style={styles.buildingMeta}>
            {building.floors.length} {building.floors.length === 1 ? 'floor' : 'floors'} ·{' '}
            {building.floors.reduce((sum, f) => sum + f.nodes.length, 0)} locations
          </Text>
        </View>
        <Text style={styles.chevron}>{expanded ? '▼' : '▶'}</Text>
      </Pressable>

      {expanded && (
        <View style={styles.floorsContainer}>
          {building.floors.map(floor => (
            <FloorSection key={floor.floorId} floor={floor} onNodeSelect={onNodeSelect} />
          ))}
        </View>
      )}
    </View>
  );
}

interface FloorSectionProps {
  floor: import('../../hooks/useLocationSearch').SearchFloor;
  onNodeSelect: (node: NavNode) => void;
}

function FloorSection({ floor, onNodeSelect }: FloorSectionProps) {
  return (
    <View style={styles.floorSection}>
      <Text style={styles.floorHeader}>Floor {floor.floorNumber}</Text>
      {floor.nodes.map(sn => (
        <NodeRow key={sn.node.id} searchNode={sn} onPress={() => onNodeSelect(sn.node)} />
      ))}
    </View>
  );
}

interface NodeRowProps {
  searchNode: import('../../hooks/useLocationSearch').SearchNode;
  onPress: () => void;
}

function NodeRow({ searchNode, onPress }: NodeRowProps) {
  const { node, buildingName, floorNumber } = searchNode;
  const badge = TYPE_BADGE[node.type] ?? '📍';
  const isAccessible = node.type === 'elevator' || node.type === 'ramp';

  return (
    <Pressable style={styles.nodeRow} onPress={onPress}>
      <Text style={styles.nodeBadge}>{badge}</Text>
      <View style={styles.nodeInfo}>
        <Text style={styles.nodeLabel}>{node.label}</Text>
        <Text style={styles.nodeSubtext}>
          {buildingName} · Floor {floorNumber}
          {node.roomNumber ? ` · Room ${node.roomNumber}` : ''}
        </Text>
      </View>
      {isAccessible && <Text style={styles.accessibleIcon}>{ACCESSIBLE_ICON}</Text>}
    </Pressable>
  );
}

